SMOKE = "import json, importlib.metadata as md, math\nfrom pathlib import Path\nimport build123d as bd\nfrom cadgen import model\nROOT=Path(__file__).resolve().parent\n@model\ndef smoke_bracket():\n    shape=bd.Box(40,20,6)-bd.Cylinder(4,6)\n    shape.label='headless-smoke-bracket'\n    return shape\nif __name__=='__main__':\n    doc=smoke_bracket()\n    doc.export(ROOT/'smoke.step',ROOT/'smoke.stl',ROOT/'smoke.glb')\n    imported=bd.import_step(str(ROOT/'smoke.step'))\n    expected=40*20*6-math.pi*4**2*6\n    assert imported.is_valid\n    assert math.isclose(imported.volume,expected,rel_tol=1e-7)\n    receipt={'cadgen':md.version('cadgen'),'build123d':md.version('build123d'),'cadquery-ocp-novtk':md.version('cadquery-ocp-novtk'),'document_id':doc.id,'valid':imported.is_valid,'volume_mm3':imported.volume,'expected_volume_mm3':expected,'artifacts':{p.name:p.stat().st_size for p in (ROOT/'smoke.step',ROOT/'smoke.stl',ROOT/'smoke.glb')}}\n    (ROOT/'headless-receipt.json').write_text(json.dumps(receipt,indent=2)+'\\n')\n    print(json.dumps(receipt))\n"
expected = hashlib.sha256(REQUIREMENTS.encode()).hexdigest()
marker = ROOT/'runtime-installed.sha256'
log = ROOT/'bootstrap.log'
def run(args):
    with log.open('a') as f:
        result = subprocess.run(args, stdout=f, stderr=subprocess.STDOUT, env=os.environ)
    text = re.sub(r'token=[^\s]+', 'token=[REDACTED]', log.read_text())
    log.write_text(text)
    if result.returncode:
        sys.stderr.write(text[-6000:])
        raise SystemExit(result.returncode)
if not marker.exists() or marker.read_text() != expected:
    if not (RUNTIME/'bin/python').exists():
        venv.EnvBuilder(with_pip=True).create(RUNTIME)
    lock = ROOT/'runtime.requirements.txt'
    lock.write_text(REQUIREMENTS)
    run([str(RUNTIME/'bin/python'), '-m', 'pip', 'install', '--require-hashes', '-r', str(lock)])
    marker.write_text(expected)
# Load the headless CAD shared-library closure without root or task-image changes.
import platform, urllib.request
assert platform.machine() in ('x86_64', 'amd64'), 'This pinned runtime targets the benchmark amd64 image'
